-- koloni-287: Bilgi arşivi ek kayıtlar (yalnız veri): Muğla arısı morfometrisi, Yeninar 2009 gezginci melez, Kafkas×Karadeniz×Muğla tahmini (uzman tahmini).
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-morfo','irk','Muğla arısı morfometrisi: arı değil koloni büyüklüğü farkı','Ön kanat uzunluğu: Muğla 9,167 mm · Orta Anadolu 9,127 · Kafkas 9,306 · Karniyol 9,403 (Ruttner).
Dil uzunluğu: Muğla 6,579 · Orta Anadolu 6,489 · Kafkas 6,967 mm.
Muğla arısı bireysel olarak Kafkas''tan küçük; verim farkı arı boyundan değil koloni büyüklüğünden: Akyol''da arılı çerçeve Muğla 11,57, Kafkas 8,17.','kaynaklı','[{"ad":"J. Anim. Vet. Adv. 5(9):771–774 (2006)","url":"https://www.makhillpublications.co/files/published-files/mak-java/2006/9-771-774.pdf"},{"ad":"DrawWing — wing length (Ruttner değerleri)","url":"https://honeybee.drawwing.org/book/wing-length"},{"ad":"Akyol (1998) tez özeti","url":"https://tezara.org/theses/77039"}]'::jsonb,50) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('melez-yeninar','melez','Yeninar, Akyol & Şahinler 2009: gezginci güzergâhta melez','Güzergâh: Çukurova narenciye → Uluışla yayla → Harran.
Bal (kg/koloni): Muğla ana × Kafkas baba 55,3 · saf Muğla 43,9 · saf Kafkas 36,3 · Kafkas ana × Muğla baba 33,1.
Akyol (1998) ile tutarlı: Muğla ana × Kafkas baba en yüksek. Bizim güzergâha (Antalya → Tekman → Muğla) aktarım: uzman tahmini.
Kitap: Yeninar, «Kadim Topraklarda Arı ve Arıcının Yolculuğu: Göçer Arıcılık».','karışık','[{"ad":"Yeninar, Akyol & Şahinler (2009), J. Anim. Vet. Adv.","url":"https://doi.org/10.3923/javaa.2009.995.999"},{"ad":"Yeninar, Kadim Topraklarda Arı ve Arıcının Yolculuğu – Göçer Arıcılık","url":"https://www.aridostum.org.tr/wp-content/uploads/2024/10/Kadim-Topraklarda-Ari-ve-Aricinin-Yolculugu-Gocer-Aricilik-Prof.-Dr.-Halil-YENINAR.pdf"}]'::jsonb,30) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('goc-kkm','goc','Kafkas × Karadeniz × Muğla üçlü melez: verim tahmini','Bu üçlü melezle yapılmış çalışma: Veri yok.
Tahmin (uzman tahmini): 25–50 kg/koloni, en olası 30–40 kg — Antalya 5–12, Tekman 10–22, Muğla 8–18 kg.
Dayanak: Karadeniz (Ordu) ekotipleri düşük verimli — Korgan 13,3 · Camili 12,6 · Yığılca 9,3 kg; Beypazarı × Tokat melezi 16,7 kg. Muğla × Kafkas melezine göre Karadeniz katkısı verimi düşürebilir (uzman tahmini).','uzman tahmini','[{"ad":"Karadeniz ekotipleri verim karşılaştırması (Ordu)","url":"https://dergipark.org.tr/tr/pub/zm/article/814315"},{"ad":"Beypazarı × Tokat melezi (Turk J Vet Anim Sci 23)","url":"https://journals.tubitak.gov.tr/veterinary/issues/vet-99-23-ek1/vet-23-ek1-2-96163.pdf"}]'::jsonb,20) on conflict (id) do update set klasor_id=excluded.klasor_id, baslik=excluded.baslik, icerik=excluded.icerik, durum=excluded.durum, kaynaklar=excluded.kaynaklar, sira=excluded.sira, updated_at=now();
